<script setup>
import {computed, nextTick, ref, watch} from 'vue'

import SQLCode from '../../shared/components/SQLCode.vue'
import MarkdownContent from '../../shared/components/MarkdownContent.vue'
import HelpTip from '../../shared/components/HelpTip.vue'
import NacosPlanPreview from './NacosPlanPreview.vue'
import SQLPlanPreview from './SQLPlanPreview.vue'
import RedisPlanPreview from './RedisPlanPreview.vue'
import {resourceContentGroups,resourceContentSummary,resourceChangePreview,sqlContentSelection} from '../deliveryContentPresentation.js'

const props=defineProps({changes:{type:Array,default:()=>[]},environment:String,preview:Object,autoExpand:Boolean})
const groups=computed(()=>resourceContentGroups(props.changes))
const expanded=ref([]),active=ref(null),root=ref(null)
watch(()=>[props.autoExpand,groups.value.flatMap(group=>group.changes.map(change=>change.id)).join(',')],()=>{
  const ids=groups.value.flatMap(group=>group.changes.map(change=>change.id))
  expanded.value=expanded.value.filter(id=>ids.includes(id))
  if(props.autoExpand&&!expanded.value.length&&ids.length)expanded.value=[ids[0]]
},{immediate:true})
const alias=change=>(change.sql||change.nacos||change.redis)?.resource_alias||'未配置资源'
const plans=change=>resourceChangePreview(props.preview,change)
async function reveal(ids){
  const available=props.changes.filter(change=>ids.includes(change.id))
  expanded.value=[...new Set([...expanded.value,...available.map(change=>change.id)])]
  active.value=available[0]?.id
  await nextTick()
  const target=[...(root.value?.querySelectorAll('[data-content-change]')||[])].find(element=>element.dataset.contentChange===String(active.value))
  target?.scrollIntoView({block:'nearest',behavior:'instant'})
  focusControl(target,{preventScroll:true})
}
defineExpose({reveal})

import {focusControl} from '../../shared/focusControl.js'


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Badge,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'
</script>
<template><div ref="root" class="resource-delivery-content"><section v-for="group in groups" :key="group.kind" :aria-label="group.label" class="content-group"><h4>{{group.label}} · {{group.changes.length}}</h4><Accordion class="resource-content-list" type="multiple" :model-value="(expanded||[]).map(String)" @update:model-value="expanded=$event;"><AccordionItem v-for="change in group.changes" :value="String(change.id)"><AccordionTrigger><div class="content-summary"><strong>#{{change.id}} · {{change.title}}</strong><span>{{change.service||'未关联应用'}} · {{alias(change)}} · {{resourceContentSummary(change,environment)}}</span></div></AccordionTrigger><AccordionContent force-mount v-show="!(!(expanded||[]).map(String).includes(String(change.id)))"><template #extra><Badge :variant="(change.status==='ready'?'blue':'orange')==='red'?'destructive':'secondary'">{{change.status==='ready'?'内容已就绪':'待补齐'}}</Badge></template><article :data-content-change="change.id" tabindex="-1" :class="{'content-located':active===change.id}"><dl class="grid min-w-0 gap-4 sm:grid-cols-2"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">所属应用</dt><dd class="min-w-0 break-words">{{change.service||'未关联应用'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">逻辑资源</dt><dd class="min-w-0 break-words">{{alias(change)}}</dd></div><div v-if="change.summary" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">变更说明</dt><dd class="min-w-0"><MarkdownContent :content="change.summary"/></dd></div><div v-if="change.rollback_plan" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">回退说明</dt><dd class="min-w-0"><MarkdownContent :content="change.rollback_plan" label="回退说明"/></dd></div></dl><template v-if="plans(change).length"><NacosPlanPreview v-if="change.kind==='nacos'" :plans="plans(change)"/><SQLPlanPreview v-if="change.kind==='mysql'" :plans="plans(change)"/><RedisPlanPreview v-if="change.kind==='redis'" :plans="plans(change)"/></template><template v-else-if="change.kind==='nacos'&&change.nacos"><dl class="grid min-w-0 gap-4 sm:grid-cols-2"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">默认 Data ID</dt><dd class="min-w-0 break-words">{{change.nacos.data_id||'使用环境绑定'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">默认 Group</dt><dd class="min-w-0 break-words">{{change.nacos.group||'使用环境绑定'}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">配置格式</dt><dd class="min-w-0 break-words">{{change.nacos.format||'未配置'}}</dd></div></dl><div class="detail-label">期望配置<HelpTip text="这里是变更声明。目标环境的 Data ID、Group、当前值和配置差异在预检时解析确认。"/></div><p v-if="change.nacos.restore">恢复执行单 #{{change.nacos.restore.run_id}} 中变更 #{{change.nacos.restore.change_id}} 的历史快照；恢复差异在预检中核对。</p><div v-else-if="change.nacos.entries?.length" class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:480}).y?({x:480}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:480}).x||({x:480}).minWidth||480)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(200)+'px'}">配置项</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead><TableHead :style="{width:(200)+'px'}">期望值</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (change.nacos.entries.map((entry,index)=>({...entry,index}))||[])" :key="typeof (&quot;index&quot;)==='function'?(&quot;index&quot;)(record):record[&quot;index&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["key"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.action==='delete'?'删除项':'设置值'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><span class="config-value">{{record.action==='delete'?'（删除）':record.value}}</span></template></div></TableCell></TableRow></template><TableRow v-if="!(change.nacos.entries.map((entry,index)=>({...entry,index}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><Empty v-else><EmptyHeader><EmptyDescription>{{"尚未填写配置项"}}</EmptyDescription></EmptyHeader></Empty></template><template v-else-if="change.kind==='mysql'&&change.sql"><div class="detail-label">{{sqlContentSelection(change,environment).label}}<Badge v-if="!sqlContentSelection(change,environment).skip" variant="secondary">影响行数上限 {{change.sql.max_affected_rows??'未设置'}}</Badge><HelpTip text="当前展示所选环境的脚本声明；实际数据库、执行语句及影响范围以预检结果为准。"/></div><p v-if="sqlContentSelection(change,environment).reason">原因：{{sqlContentSelection(change,environment).reason}}</p><SQLCode v-if="!sqlContentSelection(change,environment).skip" :content="sqlContentSelection(change,environment).content||'尚未填写 SQL'"/></template><template v-else-if="change.kind==='redis'&&change.redis"><div class="detail-label">待执行命令<HelpTip text="目标连接、DB 和 Key 前缀在预检中解析。这里只展示声明，不执行命令。"/></div><pre>{{change.redis.commands||'尚未填写命令'}}</pre></template><MarkdownContent v-else :content="change.reference||change.summary||'尚无详细内容，请在来源变更中补齐。'" label="操作说明"/></article></AccordionContent></AccordionItem></Accordion></section></div></template>
<style scoped>.resource-delivery-content,.content-group{min-width:0}.content-group+.content-group{margin-top:20px}.content-group h4{margin:0 0 10px;font-size:.875rem}.content-summary{display:grid;gap:4px;min-width:0}.content-summary strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.content-summary span{font-size:.75rem;color:var(--muted-foreground);overflow-wrap:anywhere}.detail-label{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:12px 0 8px;font-size:.75rem;font-weight:600}article{min-width:0;scroll-margin:16px}article.content-located{outline:2px solid var(--brand);outline-offset:6px}pre,.config-value{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.75rem}pre{margin:0;padding:12px;background:var(--panel2)}p{overflow-wrap:anywhere;font-size:.75rem;color:var(--muted-foreground)}</style>
